  function parseNarrow(rows,headers){const idx={};headers.forEach((h,i)=>{const t=headerType(h);if(t&&idx[t]===undefined)idx[t]=i});let current="classificatoria",block=0,lastRank=0;const out=[];rows.slice(1).forEach((cells,rowIndex)=>{const explicit=phaseFromText(cells[idx.etapa]);const title=phaseFromText(cells.join(" "));const jogador=String(cells[idx.jogador]||"").trim();if(title&&!jogador){current=title;block=Math.max(0,PHASES.indexOf(title));lastRank=0;return}if(!jogador)return;const rank=num(cells[idx.rank]);if(!explicit&&rank&&lastRank&&rank<=lastRank&&block<PHASES.length-1){block++;current=PHASES[block]}lastRank=rank||lastRank;const etapa=explicit||current;const equipe=String(cells[idx.equipe]||"").trim();const abates=num(cells[idx.abates]);const quedas=num(cells[idx.quedas]);out.push({rank:rank||rowIndex+1,jogador,equipe,etapa,abates,quedas,media:quedas?abates/quedas:0,roleGroup:roleGroup(cells[idx.role])})});return out}
  function parseWide(text){const rows=splitRows(text);if(!rows.length)return[];const headers=rows[0].map(h=>String(h||"").trim());const starts=headers.map((h,i)=>headerType(h)==="jogador"?i:-1).filter(i=>i>=0);if(starts.length>=2){const out=[];starts.forEach((start,block)=>{const end=starts[block+1]??headers.length;const etapa=PHASES[block]||`fase-${block+1}`;const idx={};for(let i=start;i<end;i++){const t=headerType(headers[i]);if(t&&idx[t]===undefined)idx[t]=i}rows.slice(1).forEach((cells,rowIndex)=>{const jogador=String(cells[idx.jogador]||"").trim();if(!jogador)return;const equipe=String(cells[idx.equipe]||"").trim();const abates=num(cells[idx.abates]);const quedas=num(cells[idx.quedas]);out.push({rank:rowIndex+1,jogador,equipe,etapa,abates,quedas,media:quedas?abates/quedas:0,roleGroup:roleGroup(cells[idx.role])})})});return out}return parseNarrow(rows,headers)}
  function parseKillsJSON(data){const out=[];const add=(arr,etapa)=>{(arr||[]).forEach((r,i)=>{const jogador=String(r.jogador||r.nickname||r.nick||r.nome||r.player||"").trim();if(!jogador)return;const equipe=String(r.equipe||r.team||r.time||"").trim();const abates=num(r.abates??r.kills??r.k);const quedas=num(r.quedas??r.q);const fase=phaseFromText(r.etapa||r.fase||etapa)||etapa||"classificatoria";out.push({rank:num(r.rank??r["#"])||i+1,jogador,equipe,etapa:fase,abates,quedas,media:quedas?abates/quedas:0,roleGroup:roleGroup(r.role||r.funcao||r.posicao||r["posição"])})})};if(Array.isArray(data)){add(data,"classificatoria");return out}if(data&&data.fases){PHASES.forEach(p=>add(data.fases[p],p));return out}if(data&&Array.isArray(data.rows)){add(data.rows);return out}if(data&&Array.isArray(data.data)){add(data.data);return out}return out}
