  async function loadPlayers(){if(playersCache)return playersCache;try{const byPT=new Map,byP=new Map,teamByP=new Map;parseSimpleData(await fetchText(PLAYERS_URL)).forEach(r=>{const jogador=cell(r,["jogador","player","nick","nome","nickname"]),equipe=cell(r,["time","equipe","team"]),role=roleGroup(cell(r,["posição","posicao","função","funcao","role"]));if(!jogador)return;byP.set(key(jogador),role);if(equipe){byPT.set(`${key(jogador)}|${key(equipe)}`,role);teamByP.set(key(jogador),equipe)}});playersCache={byPT,byP,teamByP};return playersCache}catch(e){console.warn("LAFF players",e);playersCache={byPT:new Map,byP:new Map,teamByP:new Map};return playersCache}}
