  function stageRows(rows){if(stage!=="geral")return rows.filter(r=>r.etapa===stage);const map=new Map;rows.filter(r=>PHASES.includes(r.etapa)).forEach(r=>{const id=`${key(r.jogador)}|${key(r.equipe)}`;const cur=map.get(id)||{...r,etapa:"geral",abates:0,quedas:0};cur.abates+=Number(r.abates||0);cur.quedas+=Number(r.quedas||0);cur.media=cur.quedas?cur.abates/cur.quedas:0;map.set(id,cur)});return[...map.values()]}
